const ee = require('@google/earthengine');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cambodia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'))
    .first()
    .geometry();

  const startYear = 2014;
  const endYear = 2017;

  // Initialize total fire counts for February and October
  let totalFireFeb = 0;
  let totalFireOct = 0;

  // Store intermediate validation info
  const validationInfo = [];

  // Function to get active fire data for a given date range
  const getFireData = (start, end, geometry) => {
    return ee.ImageCollection('MODIS/006/MCD14DL') // MODIS/006/MCD14DL is the recommended collection
      .filterDate(start, end)
      .filterBounds(geometry)
      .select('Fire'); // Select the 'Fire' band which contains fire pixel count
  };

  // Loop through each year
  for (let year = startYear; year <= endYear; year++) {
    // February Period
    const dateFebStart = ee.Date.fromYMD(year, 2, 1);
    const dateFebEnd = ee.Date.fromYMD(year, 2, 28).advance(1, 'day'); // Handles leap years implicitly up to Feb 29

    // October Period
    const dateOctStart = ee.Date.fromYMD(year, 10, 1);
    const dateOctEnd = ee.Date.fromYMD(year, 10, 31).advance(1, 'day');

    // Data Acquisition & Check for February
    const collectionFeb = getFireData(dateFebStart, dateFebEnd, cambodia);
    const sizeFeb = await collectionFeb.size().getInfo();
    validationInfo.push(`${year} Feb Images: ${sizeFeb}`);

    if (sizeFeb > 0) {
      const sumFireFeb = await collectionFeb.sum()
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: cambodia,
          scale: 1000, // MODIS resolution is ~1km
          maxPixels: 1e9,
          tileScale: 4
        }).get('Fire').getInfo();
      if (sumFireFeb !== null && sumFireFeb !== undefined) {
        totalFireFeb += sumFireFeb;
        validationInfo.push(`  ${year} Feb Fire Sum: ${sumFireFeb}`);
      } else {
        validationInfo.push(`  ${year} Feb Fire Sum: Calculation Failed (null/undefined)`);
        console.log(validationInfo.join('\n'));
        console.log("C3");
        return;
      }
    }

    // Data Acquisition & Check for October
    const collectionOct = getFireData(dateOctStart, dateOctEnd, cambodia);
    const sizeOct = await collectionOct.size().getInfo();
    validationInfo.push(`${year} Oct Images: ${sizeOct}`);

    if (sizeOct > 0) {
      const sumFireOct = await collectionOct.sum()
        .reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: cambodia,
          scale: 1000,
          maxPixels: 1e9,
          tileScale: 4
        }).get('Fire').getInfo();

      if (sumFireOct !== null && sumFireOct !== undefined) {
        totalFireOct += sumFireOct;
        validationInfo.push(`  ${year} Oct Fire Sum: ${sumFireOct}`);
      } else {
        validationInfo.push(`  ${year} Oct Fire Sum: Calculation Failed (null/undefined)`);
        console.log(validationInfo.join('\n'));
        console.log("C3");
        return;
      }
    }
  }

  // Check for C1 (Empty Collection) at an aggregated level
  // If no images for any period, it's C1.
  if (validationInfo.every(line => line.includes('Images: 0'))) {
    console.log(validationInfo.join('\n'));
    console.log("C1");
    return;
  }

  // Check for C3 (Calculation Failure) for aggregated sums
  if (totalFireFeb === null || totalFireFeb === undefined || isNaN(totalFireFeb) ||
      totalFireOct === null || totalFireOct === undefined || isNaN(totalFireOct)) {
    console.log(validationInfo.join('\n'));
    console.log(`Final Feb Total: ${totalFireFeb}, Final Oct Total: ${totalFireOct}`);
    console.log("C3");
    return;
  }

  // Check for C2 (No Valid Pixels)
  // If all reductions resulted in 0, it means no fires were detected, which is a valid result, not C2.
  // C2 would be if the geometry was empty or scale too small etc. Here, 0 is a valid measurement.
  // No need for a separate C2 check here beyond the C1 check.

  // 4. Validation & Final Answer
  console.log(validationInfo.join('\n'));
  console.log(`Total active fire pixels (Feb 2014-2017): ${totalFireFeb}`);
  console.log(`Total active fire pixels (Oct 2014-2017): ${totalFireOct}`);

  if (totalFireFeb > totalFireOct) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No (includes equal or less)
  }
}

// Helper to authenticate and initialize Earth Engine
async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(require('./.earthsense-436113-b294c5f5c2dc.json'), resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
